  const ROOM_NOTE = "(You may cast either half. That door unlocks on the battlefield. As a sorcery, you may pay the mana cost of a locked door to unlock it.)";
  const ROOM = (a, b, extra = {}) => ({ type: "Enchantment — Room", layout: "room", ...extra,
    faces: [{ type: "Enchantment — Room", ...a }, { type: "Enchantment — Room", ...b }],
    text: `${a.name} ${a.cost}: ${a.text} // ${b.name} ${b.cost}: ${b.text} ${ROOM_NOTE}` });
  const ENDURING = { effect: { returnAsEnchantment: true } };
  const ENDURING_TEXT = (name) => `When ${name} dies, if it was a creature, return it to the battlefield under its owner's control. It's an enchantment. (It's not a creature.)`;
  const IMPENDING = (n, cost) => `Impending ${n}—${cost} (If you cast this spell for its impending cost, it enters with ${["", "one", "two", "three", "four", "five"][n]} time counters and isn't a creature until the last is removed. At the beginning of your end step, remove a time counter from it.)`;
  const VERGE = (a, b, types) => ({ type: "Land", produces: a, verge: { color: b, types },
    text: `{T}: Add {${a}}. {T}: Add {${b}}. Activate only if you control ${types.map((t) => (/^[AEIOU]/.test(t) ? "an " : "a ") + t).join(" or ")}.` });
